class ServiceLocator {
  private static services = new Map<string, unknown>();
  static register(name: string, service: unknown) { this.services.set(name, service); }
  static get<T>(name: string): T { return this.services.get(name) as T; }
}

ServiceLocator.register("audio", new AudioManager());

// Intermediate layers no longer need to know AudioManager exists
class GameLoop { constructor() { this.level = new Level(); } }
class Level { constructor() { this.enemy = new Enemy(); } }
class Enemy {
  onDeath() {
    ServiceLocator.get<AudioManager>("audio").play("enemy-death"); // looked up only when needed
  }
}
